def minFlips(grid):
    m, n = len(grid), len(grid[0])
    ans = 0

    # Orbits of 4 cells: any 0/4 ones keeps the count divisible by 4
    for i in range(m // 2):
        for j in range(n // 2):
            ones = (grid[i][j] + grid[i][n - 1 - j]
                    + grid[m - 1 - i][j] + grid[m - 1 - i][n - 1 - j])
            ans += min(ones, 4 - ones)

    diff = 0        # symmetric pairs (middle row/column) with different values
    pair_ones = 0   # ones contributed by pairs that are already equal (2 per 11 pair)

    if m % 2:  # middle row pairs
        r = m // 2
        for j in range(n // 2):
            if grid[r][j] != grid[r][n - 1 - j]:
                diff += 1
            else:
                pair_ones += 2 * grid[r][j]
    if n % 2:  # middle column pairs
        c = n // 2
        for i in range(m // 2):
            if grid[i][c] != grid[m - 1 - i][c]:
                diff += 1
            else:
                pair_ones += 2 * grid[i][c]

    # Center cell must be 0 (it is the only odd contributor)
    if m % 2 and n % 2:
        ans += grid[m // 2][n // 2]

    ans += diff
    if diff == 0 and pair_ones % 4 == 2:
        ans += 2
    return ans
